/// Look up a function by exact (case-sensitive) name and kind.
pub fn lookup(name: &str, kind: FnKind) -> Option<&'static FnInfo> {
    let start = FUNCTIONS.partition_point(|f| f.name < name);
    FUNCTIONS[start..].iter().take_while(|f| f.name == name).find(|f| f.kind == kind)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sorted() {
        for w in FUNCTIONS.windows(2) {
            assert!(w[0].name <= w[1].name, "{} > {}", w[0].name, w[1].name);
        }
    }

    #[test]
    fn sum_and_count() {
        let sum = lookup("sum", FnKind::Aggregate).unwrap();
        assert_eq!(sum.kind, FnKind::Aggregate);
        assert_eq!(sum.result_name, ResultName::PrefixAndFirstArgument);
        assert_eq!(sum.prefix, Some("sum"));
        assert_eq!(sum.signatures[0].ret, Ret::Parameter0Promoted);
        assert_eq!(sum.signatures[0].params, &["Summable"]);
        let count = lookup("count", FnKind::Aggregate).unwrap();
        assert_eq!(count.prefix, Some("count"));
        assert_eq!(count.signatures[0].ret, Ret::Fixed("long"));
        assert_eq!(count.signatures[0].max_args, 0);
        assert!(lookup("sum", FnKind::Scalar).is_none());
    }

    #[test]
    fn scalars() {
        let bin = lookup("bin", FnKind::Scalar).unwrap();
        assert_eq!(bin.kind, FnKind::Scalar);
        assert_eq!(bin.result_name, ResultName::FirstArgument);
        assert_eq!(bin.signatures[0].ret, Ret::Widest);
        assert_eq!(lookup("strlen", FnKind::Scalar).unwrap().signatures[0].ret, Ret::Fixed("long"));
        assert_eq!(lookup("tostring", FnKind::Scalar).unwrap().signatures[0].ret, Ret::Fixed("string"));
        let strcat = lookup("strcat", FnKind::Scalar).unwrap();
        assert_eq!((strcat.signatures[0].min_args, strcat.signatures[0].max_args), (1, 64));
        let case = lookup("case", FnKind::Scalar).unwrap();
        assert_eq!(case.signatures[0].max_args, u8::MAX);
        assert!(lookup("todouble", FnKind::Scalar).is_some());
        assert!(lookup("toreal", FnKind::Scalar).is_some());
        assert!(lookup("no_such_function", FnKind::Scalar).is_none());
    }

    #[test]
    fn obsolete_and_both_kinds() {
        let ms = lookup("makeset", FnKind::Aggregate).unwrap();
        assert!(ms.obsolete && ms.hidden);
        assert!(!lookup("make_set", FnKind::Aggregate).unwrap().obsolete);
        // `any` exists both as a graph scalar function and as an aggregate.
        assert!(lookup("any", FnKind::Aggregate).is_some());
        assert!(lookup("any", FnKind::Scalar).is_some());
        assert_eq!(lookup("arg_max", FnKind::Aggregate).unwrap().signatures[0].ret, Ret::Custom);
    }
}
